 19→class VectorTypeTest {
 20→
 21→    // ── FieldType.VectorType construction ────────────────────────────────
 22→
 23→    @Test
 24→    void vectorType_createsWithFloat32() {
 25→        var vt = new FieldType.VectorType(FieldType.Primitive.FLOAT32, 128);
 26→        assertEquals(FieldType.Primitive.FLOAT32, vt.elementType());
 27→        assertEquals(128, vt.dimensions());
 28→    }
