 30→    @Test
 31→    void vectorType_createsWithFloat16() {
 32→        var vt = new FieldType.VectorType(FieldType.Primitive.FLOAT16, 64);
 33→        assertEquals(FieldType.Primitive.FLOAT16, vt.elementType());
 34→        assertEquals(64, vt.dimensions());
 35→    }
 36→
 37→    @Test
 38→    void vectorType_rejectsStringElementType() {
 39→        assertThrows(IllegalArgumentException.class,
 40→                () -> new FieldType.VectorType(FieldType.Primitive.STRING, 128));
 41→    }
 42→
 43→    @Test
 44→    void vectorType_rejectsInt32ElementType() {
 45→        assertThrows(IllegalArgumentException.class,
 46→                () -> new FieldType.VectorType(FieldType.Primitive.INT32, 128));
 47→    }
