 49→    @Test
 50→    void vectorType_rejectsZeroDimensions() {
 51→        assertThrows(IllegalArgumentException.class,
 52→                () -> new FieldType.VectorType(FieldType.Primitive.FLOAT32, 0));
 53→    }
 54→
 55→    @Test
 56→    void vectorType_rejectsNegativeDimensions() {
 57→        assertThrows(IllegalArgumentException.class,
 58→                () -> new FieldType.VectorType(FieldType.Primitive.FLOAT32, -1));
 59→    }
