 61→    // ── FieldType.vector() factory ───────────────────────────────────────
 62→
 63→    @Test
 64→    void vectorFactory_returnsVectorType() {
 65→        FieldType result = FieldType.vector(FieldType.Primitive.FLOAT32, 128);
 66→        assertInstanceOf(FieldType.VectorType.class, result);
