147→    // ── DocumentSerializer round-trip ────────────────────────────────────
148→
149→    private static JlsmDocument roundTrip(JlsmSchema schema, JlsmDocument doc) {
150→        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema);
151→        MemorySegment bytes = ser.serialize(doc);
152→        return ser.deserialize(bytes);
153→    }
154→
155→    @Test
156→    void documentSerializer_roundTripsFloat32Vector() {
157→        JlsmSchema schema = JlsmSchema.builder("test", 1)
158→                .vectorField("vec", FieldType.Primitive.FLOAT32, 4).build();
159→
160→        float[] vector = { 1.0f, -2.5f, 3.14f, 0.0f };
161→        JlsmDocument doc = JlsmDocument.of(schema, "vec", vector);
162→        JlsmDocument out = roundTrip(schema, doc);
163→
164→        assertFalse(out.isNull("vec"));
165→        float[] result = (float[]) out.values()[0];
166→        assertArrayEquals(vector, result);
167→    }
168→
169→    @Test
170→    void documentSerializer_roundTripsFloat16Vector() {
171→        JlsmSchema schema = JlsmSchema.builder("test", 1)
172→                .vectorField("vec", FieldType.Primitive.FLOAT16, 3).build();
173→
174→        // Store as raw IEEE 754 half-precision bits
175→        short[] vector = { Float16.fromFloat(1.0f), Float16.fromFloat(-0.5f),
176→                Float16.fromFloat(3.0f) };
177→        JlsmDocument doc = JlsmDocument.of(schema, "vec", vector);
178→        JlsmDocument out = roundTrip(schema, doc);
179→
180→        assertFalse(out.isNull("vec"));
181→        short[] result = (short[]) out.values()[0];
182→        assertArrayEquals(vector, result);
183→    }
184→
185→    @Test
186→    void documentSerializer_roundTripsNullVector() {
187→        JlsmSchema schema = JlsmSchema.builder("test", 1).field("name", FieldType.string())
188→                .vectorField("vec", FieldType.Primitive.FLOAT32, 4).build();
189→
190→        JlsmDocument doc = JlsmDocument.of(schema, "name", "test", "vec", null);
191→        JlsmDocument out = roundTrip(schema, doc);
192→
193→        assertEquals("test", out.getString("name"));
194→        assertTrue(out.isNull("vec"));
195→    }
196→}
