  6→class JsonRoundTripTest {
  7→
  8→    @Test
  9→    void roundTrip_allPrimitiveTypes() {
 10→        JlsmSchema schema = JlsmSchema.builder("test", 1).field("s", FieldType.Primitive.STRING)
 11→                .field("i32", FieldType.Primitive.INT32).field("i64", FieldType.Primitive.INT64)
 12→                .field("f32", FieldType.Primitive.FLOAT32).field("f64", FieldType.Primitive.FLOAT64)
 13→                .field("bool", FieldType.Primitive.BOOLEAN)
 14→                .field("ts", FieldType.Primitive.TIMESTAMP).build();
 15→        JlsmDocument doc = JlsmDocument.of(schema, "s", "hello", "i32", 42, "i64", 100L, "f32",
 16→                1.5f, "f64", 2.718281828, "bool", true, "ts", 1700000000000L);
 17→        JlsmDocument out = JlsmDocument.fromJson(doc.toJson(), schema);
 18→        assertEquals("hello", out.getString("s"));
 19→        assertEquals(42, out.getInt("i32"));
